const SENSITIVE_KEY = /password|secret|token|hash|pfx|certificate|credential|credenciais/i;

export function redactSensitive(value: Record<string, unknown>): Record<string, unknown> {
  const walk = (node: unknown): unknown => {
    if (Array.isArray(node)) return node.map(walk);
    if (node === null || typeof node !== 'object') return node;
    return Object.fromEntries(
      Object.entries(node as Record<string, unknown>).map(([key, child]) => [
        key,
        SENSITIVE_KEY.test(key) && child !== null && child !== undefined ? REDACTED : walk(child),
      ]),
    );
  };
  return walk(value) as Record<string, unknown>;
}

await this.dataSource.transaction(async (manager) => {
  await manager.query(`SELECT pg_advisory_xact_lock(hashtext('audit_events_partitions'))`);
  for (let offset = 0; offset <= AUDIT_PARTITION_MONTHS_AHEAD; offset++) {
    const from = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + offset, 1));
    const to = new Date(Date.UTC(from.getUTCFullYear(), from.getUTCMonth() + 1, 1));
    const name = `audit_events_${from.toISOString().slice(0, 7).replace('-', '_')}`;
    await manager.query(
      `CREATE TABLE IF NOT EXISTS "infra"."${name}" PARTITION OF "infra"."audit_events" FOR VALUES FROM ('${from.toISOString()}') TO ('${to.toISOString()}')`,
    );
  }
});

